{
  "blocks": [
    {
      "kind": "dialogue",
      "text": "王大伯直起腰，用满是老茧的手指了指黄鼠狼左后腿的根部，那里断口参差不齐，血正顺着草根往外渗，渗进泥土里，把几只蚂蚁都引来了。",
      "speaker": {
        "kind": "person",
        "name": "王大伯",
        "ref": "k1_person_王大伯"
     ,
        "status": null
      }
    }
  ],
  "choices": [
    {
