        "ref": "",
        "status": null
      },
      "stake": "low",
      "purpose": "询问这猎夹是何时夹住黄鼠狼的",
      "anchor": 0
    },
    {
      "action": "interact:decline",
      "target": {
        "kind": "person",
        "name": "王大伯",
