      "stake": "low",
      "purpose": "询问黄鼠狼盯着这边看是否有深意",
      "anchor": 0
    },
    {
      "action": "interact:decline",
      "target": {
        "kind": "person",
        "name": "王大伯",
        "ref": "",
        "status": null
      },
      "stake": "low",
      "purpose": "不想再听这晦气话，转身离开",
      "anchor": 0
    },
    {
